    //alarm
    Assert.assertNotEquals(0, runningRule.check().size());
    //silence, no alarm
    Assert.assertEquals(0, runningRule.check().size());
    //silence, no alarm
    Assert.assertEquals(0, runningRule.check().size());
    //alarm
    Assert.assertNotEquals(0, runningRule.check().size());
}

